const sqlColumn=name=>name.replaceAll(' ','_');
entityMappings.forEach(m=>{m.parameters.forEach(p=>p.column=sqlColumn(p.name));const table=m.entity==='Vendor'?'vendor_entity_data':'hrms_faas_entity_data';m.query=`SELECT\n  ${m.parameters.map(p=>p.column).join(',\n  ')}\nFROM ${table}\nWHERE business_line = '${m.lob}'\n  AND entity_type = '${m.entity}'`;});
const previousMappingEditor=mappingEditor;
function entityQuerySection(){const m=mappingDraft;return `<section class="panel"><div class="panel-head"><h2>Entity data query ${info('One query for this Business Line and Entity. Its output supplies the entity identifier and associated fields. Sample table names must be replaced with your database schema.')}</h2></div><div class="panel-body"><label class="label" for="entitySql">SQL query</label><textarea id="entitySql" spellcheck="false" aria-label="Entity data SQL query">${esc(m.query||'')}</textarea><div class="savebar" style="justify-content:flex-start"><button class="button" id="checkEntityQuery">Check mapped fields</button>${info('Checks that included field column names appear in the SELECT output. This prototype does not execute SQL or connect to HRMS, FAAS or Vendor DB.')}</div><div id="entityQueryResult" role="status"></div></div></section>`}
mappingEditor=function(){let html=previousMappingEditor();html=html.replace('<section class="panel"><div class="panel-head"><h2>Entity parameters</h2>',entityQuerySection()+'<section class="panel"><div class="panel-head"><h2>Entity fields</h2>');html=html.replace('<th>PARAMETER</th><th>DATA TYPE','<th>FIELD</th><th>QUERY COLUMN '+info('The output column returned by the SQL query for this field.')+'</th><th>DATA TYPE');mappingDraft.parameters.forEach((p,i)=>{const old=`<td><strong>${esc(p.name)}</strong>${p.identity?'<small>Entity identifier</small>':''}</td><td>Character</td>`;const replacement=`<td><strong>${esc(p.name)}</strong>${p.identity?'<small>Entity identifier</small>':''}</td><td><input type="text" class="entity-column" data-entity-column="${i}" value="${esc(p.column||'')}" aria-label="${esc(p.name)} query column"></td><td><select data-entity-type="${i}" aria-label="${esc(p.name)} data type" ${p.identity?'disabled':''}>${selectedOptions(['Character','Integer','Float'],p.type)}</select></td>`;html=html.replace(old,replacement)});return html};
function validateEntityQuery(m){if(!m.query?.trim())return 'Enter a SQL query for this entity.';const active=m.parameters.filter(p=>p.included);if(!active.some(p=>p.identity))return 'Include the entity identifier.';const columns=active.map(p=>p.column?.trim());if(columns.some(c=>!c||!/^[_a-zA-Z][_a-zA-Z0-9]*$/.test(c)))return 'Enter a valid query column for every included field.';if(new Set(columns.map(c=>c.toLowerCase())).size!==columns.length)return 'Map each included field to a different query column.';const sql=m.query.replace(/--[^\n]*/g,'').replace(/\/\*[\s\S]*?\*\//g,'');const projection=(sql.match(/^\s*SELECT\s+([\s\S]*?)\bFROM\b/i)||[])[1];if(!projection)return 'Use an explicit SELECT query with named output columns.';const missing=columns.filter(k=>!new RegExp('(?:\\bas\\s+["`]?'+k+'["`]?\\s*(?:,|$)|(?:^|,)\\s*(?:\\w+\\.)?["`]?'+k+'["`]?\\s*(?:,|$))','i').test(projection));return missing.length?'Query output is missing: '+missing.join(', '):''}
function checkEntityQuery(){const error=validateEntityQuery(mappingDraft);const result=document.getElementById('entityQueryResult');if(result)result.innerHTML=`<div class="notice ${error?'error':'success'}">${error?esc(error):'All included fields and the entity identifier are mapped. SQL execution and source data are not checked.'}</div>`;return !error}
const previousBindMappings=bindMappings;
bindMappings=function(){previousBindMappings();document.getElementById('entitySql')?.addEventListener('input',e=>{mappingDraft.query=e.target.value;document.getElementById('entityQueryResult').innerHTML=''});document.querySelectorAll('[data-entity-column]').forEach(el=>el.oninput=()=>{mappingDraft.parameters[Number(el.dataset.entityColumn)].column=el.value;document.getElementById('entityQueryResult').innerHTML=''});document.querySelectorAll('[data-entity-type]').forEach(el=>el.onchange=()=>mappingDraft.parameters[Number(el.dataset.entityType)].type=el.value);document.getElementById('checkEntityQuery')?.addEventListener('click',checkEntityQuery)};
const previousSaveMapping=saveMapping;saveMapping=function(){if(!checkEntityQuery())return false;mappingDraft.parameters.forEach(p=>p.column=p.column.trim());return previousSaveMapping()};
const previousFilterMeta=filterMeta;filterMeta=function(kind,id){if(kind==='entityFilters'){const p=riderMapping().parameters.find(p=>parameterLabel(p.name)===id);return {id,label:id,type:p?.type||'Character'}}return previousFilterMeta(kind,id)};
render();
